example.code:
 [EntityInputHook("func_button", "Kill")]
 public HookResult OnKillInput(EntityInputEvent e) {
     return HookResult.Stop;   // veto: button won't kill the activator
 }

 [EntityInputHook("*", "Toggle", HookMode.Post)]
 public void OnToggleObserved(EntityInputEvent e) { /* post: cannot block */ }

 [EntityOutputHook("trigger_multiple", "OnStartTouch")]
 public HookResult OnTriggerTouched(EntityOutputEvent e) {
     return HookResult.Continue;
 }

 [EntityOutputHook("*", "OnPlayerPickup", HookMode.Post)]
 public void OnAnyPickup(EntityOutputEvent e) { /* observer only */ }

member.example:
Pull the camera back over 2 seconds, keep it there for 5, then give it back to the game:

var camera = player.Camera;
camera.LerpDistance(150f, 400f, 2f);
camera.Maintain(CameraSetting.Distance, 5f, delay: 2f);

example.code:
// A 3 second countdown where nobody can move or be hurt.
foreach (var player in Players.GetAll())
    player.GetHeroPawn()?.Freeze(duration: 3f);

 var finish = new Zone(new Vector3(-100, -100, 0), new Vector3(100, 100, 128)) { Name = "finish" };
 finish.Entered += (zone, player, pawn) => Chat.PrintToChat(player, "You finished!");

 var safeSpot = new Vector3(0, 0, 64);
 var pit = new Zone(new Vector3(-500, -500, -300), new Vector3(500, 500, -200));
 pit.Entered += (zone, player, pawn) => pawn.Teleport(position: safeSpot);
